document.addEventListener("keydown", (event) => { const target = event.target; if (target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement || target?.isContentEditable) return; const direction = event.key === "ArrowLeft" ? "previous" : event.key === "ArrowRight" ? "next" : null; if (direction) document.querySelector(`[data-prototype-nav="${direction}"]`)?.click(); });